"""Recover areas and compare radii in all nine printed parts 1183–1187 on p. 301."""
import argparse
import json
from math import cos,pi,sin,sqrt
from polygon_circle_applications import drawing,outline,ring
from triangle_sine_area import area
from trigonometric_signs import grade
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/regular-polygon-areas.json'


def polygon(label,n,R,focus='radii',other=False,flats=False):
    points=ring(n,R,-pi/n);names=list('ABCDEF')[:n]+['_vertex'+str(i) for i in range(6,n)]
    p=dict(zip(names,points,strict=True));p['T']=(0,0);r=R*cos(pi/n);p['H']=(r,0)
    edges=outline(names)+[('T','A'),('T','B'),('T','H'),('A','H'),('B','H')]
    if focus=='area':edges.extend(('T',v) for v in names[2:])
    highlights=[('A','B'),('T','H')]
    if flats:
        p['K']=(-r,0);edges.extend([('T','K'),('H','K')]);highlights=[('H','K'),('A','B'),(names[n//2],names[n//2+1])]
    if other:
        inside=ring(6,r,pi/6);labels=['L','M','N','P','Q','V'];p.update(dict(zip(labels,inside)))
        edges.extend(outline(labels));highlights=[('L','M'),('A','B'),('T','H')]
    p['U']=(-R,-R-1);p['W']=(-R+1,-R-1);edges.append(('U','W'))
    return drawing(label,p,edges,'T',R if focus=='R' else r,highlights)


def card(n,part,question,reason,hint,steps,views,checks,caption):
    e=area(n,part,[301],question,reason,hint,steps,views,checks,refs=[114,115,116])
    e['source']['chapter']='XIII';e['review']['reviewer']='Точные условия и подпункты сверены с печатной с. 301 издания 2023; числовые ответы и отношения повторно проверены по с. 401 и независимому измерению моделей.'
    e['visualization']['caption']=caption;e['visualization']['model']['description']=caption;e['help'][1]['text']=hint
    return e


def areas():
    rows=[
        ('а',4,3*sqrt(2),2,'R=3√2 см','У квадрата диагональ 2R=6√2, значит сторона 6 и площадь 36 см².',
         'Исходное R доведено до вершины. Сторона a=R√2, квадрат стороны равен 2R².',
         ('Проверь диагональ','R²=18. Диагональ квадрата имеет квадрат 4R²=72, а сумма квадратов его двух сторон тоже 72.'),
         ('Вычисли по двум формулам','Квадрат стороны 36; также P=24 и r=3 дают Pr/2=36.'),
         ('При новом R=6√2 площадь в четыре раза больше: 144 см².','Чему равен исходный квадрат радиуса?','18','Сколько квадратных сантиметров в новой площади?','144'),
         ['36','36,0','36.0']),
        ('б',3,8/sqrt(3),.5,'P=24 см','Сторона 8 см. Высота равностороннего треугольника 4√3 см, а площадь 8·4√3/2=16√3 см².',
         'Раздели периметр на три. Площадь равностороннего треугольника равна a²√3/4.',
         ('Перейди от периметра к стороне','a=24/3=8. Высота делит основание на два отрезка по 4, поэтому h=√(8²−4²)=4√3.'),
         ('Проверь по апофеме','Вписанный радиус r=h/3=4√3/3. Умножение 24·r/2 подтверждает 16√3.'),
         ('Если P уменьшить до 12, площадь делится на четыре и равняется 4√3 см².','Какова исходная сторона, в см?','8','Каков коэффициент при √3 в новой площади?','4'),
         ['16√3','16*sqrt(3)','16sqrt(3)']),
        ('в',6,9/cos(pi/6),1/3,'r=9 см','У шестиугольника с апофемой 9 половина стороны равна r·tg30°=3√3. Значит a=6√3, P=36√3 и S=Pr/2=162√3 см².',
         'Дан радиус до стороны r, а не радиус до вершины. Найди половину стороны через tg 30°, затем примени S=Pr/2.',
         ('Построй прямоугольный треугольник TAH','TH=9. Угол ATH=30°. Тогда AH=9/√3=3√3, откуда вся сторона 6√3.'),
         ('Сложи шесть площадей','Один центральный треугольник имеет площадь (6√3·9)/2=27√3. Таких треугольников 6, получаем 162√3.'),
         ('При уменьшении r с 9 до 3 линейные размеры делятся на 3, а площадь на 9: 18√3 см².','Каков коэффициент при √3 в исходной стороне?','6','Каков коэффициент при √3 в новой площади?','18'),
         ['162√3','162*sqrt(3)','162sqrt(3)']),
        ('г',8,5*sqrt(3)/cos(pi/8),1/sqrt(3),'r=5√3 см','У восьмиугольника S=8r²·tg22,5°. Здесь r²=75 и tg22,5°=√2−1. Получаем S=600(√2−1)≈248,528137 см², до сотых 248,53. В ключе на с. 401 приведено приближённое 248,52; раннее округление √2 до 1,4142 даёт именно его.',
         'Используй точное tg22,5°=sin45°/(1+cos45°)=√2−1. Если получил 248,52 из ключа, оставь выражение точным до последнего действия: при округлении до сотых получается 248,53.',
         ('Восстанови сторону по апофеме','У половины центрального треугольника угол при T равен 22,5°. Поэтому a=2r·tg22,5°. Получаем S=na·r/2=8r²·tg22,5°.'),
         ('Сохрани точный тангенс','Формула половинного угла даёт tg22,5°=sin45°/(1+cos45°)=√2−1. Подставь r²=75: S=600(√2−1). Для сравнения, подстановка 1,4142 вместо √2 преждевременно даёт 248,52.'),
         ('Если теперь r=5 вместо 5√3, площадь 8·25(√2−1)=200(√2−1) см².','Чему равен исходный r²?','75','Каков новый коэффициент перед (√2−1)?','200'),
         ['600(√2−1)','600(√2-1)','600*(sqrt(2)-1)','248,53','248.53'])]
    answers=[]
    for part,n,R,scale,given,reason,hint,step1,step2,repeat,forms in rows:
        vs=[polygon('Исходная фигура с заданной величиной',n,R,'R' if part=='а' else 'radii'),polygon('Разбиение на центральные треугольники',n,R,'area'),polygon('Новые размеры той же правильной фигуры',n,R*scale,'area')]
